<?php
require_once __DIR__ . '/../includes/bootstrap.php';
require_role('finance_officer');
$user = current_user();
$flashes = render_flashes();
$currentPage = 'reconciliation';
$pageTitle = 'Payment Verification';
require_once __DIR__ . '/_helpers.php';
$conn = Database::getConnection();
$uid = (int)($user['id'] ?? $user['user_id'] ?? 0);
if ($uid <= 0) { http_response_code(403); exit('Invalid Finance Officer account.'); }
if (!fo_has_table($conn,'finance_payment_records') || !fo_has_table($conn,'finance_reconciliations')) { http_response_code(503); exit('Run database/financial_reconciliation.sql before using payment verification.'); }
$id = filter_input(INPUT_GET, 'schedule_id', FILTER_VALIDATE_INT);
if (!$id || $id < 1) { http_response_code(400); exit('A valid schedule_id is required.'); }
$st=$conn->prepare("SELECT * FROM stipend_schedules WHERE id=? AND status IN ('approved','processed') LIMIT 1");
$st->bind_param('i',$id);$st->execute();$schedule=$st->get_result()->fetch_assoc();$st->close();
if(!$schedule){http_response_code(404);exit('Approved or processed stipend schedule not found.');}
$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
  fo_verify_csrf(); $action=(string)($_POST['action']??'');
  if($action==='add_payment'){
    $ref=trim((string)($_POST['payment_reference']??''));$date=trim((string)($_POST['payment_date']??''));$amount=filter_var($_POST['payment_amount']??null,FILTER_VALIDATE_FLOAT);$method=trim((string)($_POST['payment_method']??''));$bank=trim((string)($_POST['bank_reference']??''));$proof=trim((string)($_POST['proof_file_reference']??''));$note=trim((string)($_POST['verification_note']??''));
    $dt=DateTime::createFromFormat('Y-m-d',$date);
    if($ref===''||strlen($ref)>120||!$dt||$dt->format('Y-m-d')!==$date||$amount===false||$amount<=0||$amount>999999999999.99){$error='Enter a unique payment reference, valid date and positive payment amount.';}
    else{$s=$conn->prepare("INSERT INTO finance_payment_records(schedule_id,payment_reference,payment_date,payment_amount,payment_method,bank_reference,proof_file_reference,verification_status,verification_note,recorded_by) VALUES(?,?,?,?,?,?,?,'pending',?,?)");if(!$s){$error='Unable to prepare payment record.';}else{$s->bind_param('issdssssi',$id,$ref,$date,$amount,$method,$bank,$proof,$note,$uid);if($s->execute()){fo_activity($conn,$uid,'payment_record_added','Payment record added for schedule '.$schedule['schedule_reference'],'payment_record',(int)$s->insert_id);fo_flash('success','Payment record added. Verify it against the bank statement or reliable proof before reconciliation.');$s->close();header('Location: '.url('finance/payment_verification.php?schedule_id='.$id));exit;}else{$error=$s->errno===1062?'That payment reference already exists. Use a unique transaction reference.':'Unable to save payment record. Check the supplied values.';$s->close();}}}
  } elseif($action==='verify_payment'){
    $pid=(int)($_POST['payment_id']??0);$decision=(string)($_POST['decision']??'');$note=trim((string)($_POST['verification_note']??''));
    if($pid<=0||!in_array($decision,['verified','disputed'],true))$error='Invalid payment verification action.';
    else{$s=$conn->prepare("UPDATE finance_payment_records SET verification_status=?, verification_note=?, verified_by=?, verified_at=NOW() WHERE id=? AND schedule_id=? AND verification_status='pending'");$s->bind_param('ssiii',$decision,$note,$uid,$pid,$id);$s->execute();$changed=$s->affected_rows;$s->close();if($changed){fo_activity($conn,$uid,$decision==='verified'?'payment_verified':'payment_disputed','Payment record '.$pid.' '.$decision,'payment_record',$pid);fo_flash('success',$decision==='verified'?'Payment marked verified.':'Payment flagged as disputed.');header('Location: '.url('finance/payment_verification.php?schedule_id='.$id));exit;}else $error='Payment record was not pending or could not be found for this schedule.';}
  } elseif($action==='reconcile'){
    $note=trim((string)($_POST['reconciliation_note']??''));
    $s=$conn->prepare("SELECT COUNT(*) total, COALESCE(SUM(payment_amount),0) actual, COALESCE(SUM(verification_status<>'verified'),0) unverified FROM finance_payment_records WHERE schedule_id=?");$s->bind_param('i',$id);$s->execute();$pay=$s->get_result()->fetch_assoc();$s->close();
    $actual=(float)($pay['actual']??0);$unverified=(int)($pay['unverified']??0);$expected=(float)$schedule['total_amount'];$variance=round($actual-$expected,2);
    if((int)($pay['total']??0)===0){$error='Add at least one payment record before reconciling.';}
    elseif($unverified>0){$error='All payment records must be verified before reconciliation.';}
    else{$status=abs($variance)<0.005?'matched':($variance<0?'short_payment':'overpayment');$s=$conn->prepare("INSERT INTO finance_reconciliations(schedule_id,expected_amount,actual_amount,variance_amount,reconciliation_status,reconciliation_note,reconciled_by) VALUES(?,?,?,?,?,?,?)");$s->bind_param('idddssi',$id,$expected,$actual,$variance,$status,$note,$uid);if($s->execute()){fo_activity($conn,$uid,'financial_reconciliation_'.$status,'Reconciled '.$schedule['schedule_reference'].'; expected '.number_format($expected,2,'.','').' actual '.number_format($actual,2,'.',''),'reconciliation',$id);fo_flash($status==='matched'?'success':'warning',$status==='matched'?'Reconciliation matched the schedule total.':('Reconciliation recorded with variance of '.fo_money($variance).'. Review the discrepancy before taking further action.'));$s->close();header('Location: '.url('finance/payment_verification.php?schedule_id='.$id));exit;}else{$error='Unable to save reconciliation record.';$s->close();}}
  } else {$error='Unknown action.';}
}
$st=$conn->prepare("SELECT * FROM finance_payment_records WHERE schedule_id=? ORDER BY created_at DESC,id DESC");$st->bind_param('i',$id);$st->execute();$payments=$st->get_result()->fetch_all(MYSQLI_ASSOC);$st->close();
$st=$conn->prepare("SELECT r.*,u.first_name,u.last_name FROM finance_reconciliations r LEFT JOIN users u ON u.id=r.reconciled_by WHERE r.schedule_id=? ORDER BY r.id DESC LIMIT 10");$st->bind_param('i',$id);$st->execute();$reconciliations=$st->get_result()->fetch_all(MYSQLI_ASSOC);$st->close();
$actual=0.0;$unverified=0;foreach($payments as $p){$actual+=(float)$p['payment_amount'];if($p['verification_status']!=='verified')$unverified++;}$expected=(float)$schedule['total_amount'];$variance=round($actual-$expected,2);
require __DIR__.'/_layout_start.php';?>
<div class="fo-page-header"><div><span>Finance Controls / Reconciliation</span><h2>Payment Verification</h2><p>Schedule <?=e($schedule['schedule_reference'])?> · <?=e($schedule['programme_name']?:'All programmes')?> · <?=e(fo_date($schedule['period_start']))?> – <?=e(fo_date($schedule['period_end']))?></p></div><a class="fo-btn fo-btn--secondary" href="<?=url('finance/reconciliation.php')?>"><i class="fas fa-arrow-left"></i> Back to Reconciliation</a></div>
<?php if($error!==''):?><div class="fo-alert fo-alert--danger"><i class="fas fa-circle-exclamation"></i><div><?=e($error)?></div></div><?php endif;?>
<div class="fo-stats fo-stats--4"><article><i class="fas fa-file-invoice-dollar"></i><strong><?=e(fo_money($expected))?></strong><span>Expected schedule amount</span></article><article><i class="fas fa-receipt"></i><strong><?=e(fo_money($actual))?></strong><span>Total recorded payments</span></article><article><i class="fas fa-scale-balanced"></i><strong><?=e(fo_money($variance))?></strong><span>Variance (payments minus expected)</span></article><article><i class="fas fa-shield-halved"></i><strong><?=number_format($unverified)?></strong><span>Records not verified</span></article></div>
<div class="fo-card"><div class="fo-card__header"><h3>Record a Payment</h3><p>Record only payments supported by transaction evidence. This form does not initiate a bank transfer.</p></div><form method="post" class="fo-recon-form"><input type="hidden" name="csrf_token" value="<?=e(fo_csrf_token())?>"><input type="hidden" name="action" value="add_payment"><label>Payment / transaction reference<input name="payment_reference" maxlength="120" required></label><label>Payment date<input type="date" name="payment_date" max="<?=date('Y-m-d')?>" required></label><label>Payment amount (ZAR)<input type="number" name="payment_amount" min="0.01" step="0.01" required></label><label>Payment method<input name="payment_method" maxlength="80" placeholder="EFT, bank transfer, etc."></label><label>Bank reference<input name="bank_reference" maxlength="160"></label><label>Proof-of-payment reference<input name="proof_file_reference" maxlength="255" placeholder="File name or document reference"></label><label class="fo-recon-form__wide">Notes<textarea name="verification_note" maxlength="1000" rows="2"></textarea></label><div class="fo-recon-form__wide"><button class="fo-btn fo-btn--primary" type="submit"><i class="fas fa-plus"></i> Add Payment Record</button></div></form></div>
<div class="fo-card" style="margin-top:1.25rem"><div class="fo-card__header"><h3>Payment Records</h3><p>Verify each record against a bank statement or other approved evidence.</p></div><?php if(!$payments):?><div class="fo-empty"><i class="fas fa-receipt"></i><strong>No payment records yet</strong><span>Add transaction records above to begin verification.</span></div><?php else:?><div class="fo-table-wrap"><table><thead><tr><th>Reference</th><th>Date</th><th>Amount</th><th>Evidence</th><th>Status</th><th>Verification</th></tr></thead><tbody><?php foreach($payments as $p):?><tr><td><strong><?=e($p['payment_reference'])?></strong><span><?=e($p['payment_method']?:'Method not specified')?> · <?=e($p['bank_reference']?:'No bank reference')?></span></td><td><?=e(fo_date($p['payment_date']))?></td><td><?=e(fo_money($p['payment_amount']))?></td><td><?=e($p['proof_file_reference']?:'Not provided')?></td><td><span class="fo-status fo-status--<?= $p['verification_status']==='verified'?'success':($p['verification_status']==='disputed'?'danger':'warning')?>"><?=e(fo_label($p['verification_status']))?></span><?php if(!empty($p['verification_note'])):?><span><?=e($p['verification_note'])?></span><?php endif;?></td><td><?php if($p['verification_status']==='pending'):?><form method="post" class="fo-inline-form"><input type="hidden" name="csrf_token" value="<?=e(fo_csrf_token())?>"><input type="hidden" name="payment_id" value="<?=(int)$p['id']?>"><input type="text" name="verification_note" maxlength="1000" placeholder="Verification note"><button class="fo-btn fo-btn--primary" name="action" value="verify_payment" type="submit" onclick="this.form.decision.value='verified'">Verify</button><button class="fo-btn fo-btn--secondary" name="action" value="verify_payment" type="submit" onclick="this.form.decision.value='disputed'">Flag</button><input type="hidden" name="decision" value="verified"></form><?php else:?><span><?=e(fo_datetime($p['verified_at']??null))?></span><?php endif;?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></div>
<div class="fo-card" style="margin-top:1.25rem"><div class="fo-card__header"><h3>Reconcile Schedule</h3><p>Reconciliation requires every recorded payment to be verified. A variance is recorded, not silently cleared.</p></div><form method="post" class="fo-recon-form"><input type="hidden" name="csrf_token" value="<?=e(fo_csrf_token())?>"><input type="hidden" name="action" value="reconcile"><label class="fo-recon-form__wide">Reconciliation notes<textarea name="reconciliation_note" maxlength="1000" rows="3" placeholder="Explain matching evidence or any discrepancy"></textarea></label><div class="fo-recon-form__wide"><button type="submit" class="fo-btn fo-btn--primary" <?=(!$payments||$unverified>0)?'disabled':''?>><i class="fas fa-scale-balanced"></i> Record Reconciliation</button> <?php if(!$payments):?><small>Add payment records first.</small><?php elseif($unverified>0):?><small>Verify or flag all payment records before reconciling.</small><?php endif;?></div></form></div>
<div class="fo-card" style="margin-top:1.25rem"><div class="fo-card__header"><h3>Reconciliation History</h3></div><?php if(!$reconciliations):?><p>No reconciliation attempts have been recorded.</p><?php else:?><div class="fo-table-wrap"><table><thead><tr><th>Date</th><th>Expected</th><th>Actual</th><th>Variance</th><th>Result</th><th>Officer</th><th>Notes</th></tr></thead><tbody><?php foreach($reconciliations as $rec):?><tr><td><?=e(fo_datetime($rec['reconciled_at']??null))?></td><td><?=e(fo_money($rec['expected_amount']))?></td><td><?=e(fo_money($rec['actual_amount']))?></td><td><?=e(fo_money($rec['variance_amount']))?></td><td><span class="fo-status fo-status--<?= $rec['reconciliation_status']==='matched'?'success':'warning'?>"><?=e(fo_label($rec['reconciliation_status']))?></span></td><td><?=e(trim(($rec['first_name']??'').' '.($rec['last_name']??''))?:'Unknown')?></td><td><?=e($rec['reconciliation_note']?:'—')?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></div>
<?php require __DIR__.'/_layout_end.php'; ?>
